import {makeId} from './id.js';
import {t,esc,language} from './i18n.js';import {config} from './config.js';import {configured,intake} from './api.js';import {track,firstTouch,getSession,consent} from './tracking.js';
let step=0,started=false,submitting=false,token='',widget,success=null;
const data={project_type:'',budget:'',deadline:'',description:'',name:'',method:'WhatsApp',contact:'',consent:false,website:'',request_id:makeId()};
const keys=['type','budget','deadline','description','contacts','confirm'];const types=['landing','corporate','commerce','app','ux','other'];
function read(){document.querySelectorAll('#brief [name]').forEach(el=>{if(el.type==='radio'){if(el.checked)data[el.name]=el.value}else if(el.type==='checkbox')data[el.name]=el.checked;else data[el.name]=el.value})}
const label=(key)=>esc(t(key));const input=(name,key,type='text',autocomplete='',max=160)=>`<label class="field">${label(key)}<input type="${type}" name="${name}" value="${esc(data[name])}" ${autocomplete?'autocomplete="'+autocomplete+'"':''} maxlength="${max}" required></label>`;
function choices(name,values){return `<div class="choices">${values.map(v=>`<label class="choice"><input type="radio" name="${name}" value="${esc(v)}" ${data[name]===v?'checked':''} required><span>${esc(t(v))}</span></label>`).join('')}</div>`}
function message(key){const el=document.querySelector('#form-error');if(el)el.textContent=t(key)}
export function renderForm(){const host=document.querySelector('#project-form');if(!host)return;if(widget!==undefined&&window.turnstile){window.turnstile.remove(widget);widget=undefined;token=''}
 if(success){host.innerHTML=`<div class="success-mark">↗</div><h3>${label('success')}</h3><p>${label('successDesc')}</p><p class="mono">${esc(success.lead_id)}</p><a class="btn" data-event="whatsapp_click" href="https://wa.me/${config.whatsapp}?text=${encodeURIComponent('ID: '+success.lead_id)}">${label('continueWA')} ↗</a>`;return}
 let content='';if(step===0)content=choices('project_type',types);if(step===1)content=choices('budget',config.budgets);if(step===2)content=choices('deadline',['urgent','weeks','months','flexible']);if(step===3)content=`<label class="field">${label('description')}<textarea name="description" maxlength="4000" required minlength="10">${esc(data.description)}</textarea></label>`;if(step===4)content=input('name','name','text','name',100)+`<label class="field">${label('contactMethod')}<select name="method">${['WhatsApp','Telegram','email','phone'].map(m=>`<option value="${m}" ${m===data.method?'selected':''}>${esc(t(m))}</option>`).join('')}</select></label>`+input('contact','contactValue','text','',160)+`<label class="consent-label"><input name="consent" type="checkbox" required ${data.consent?'checked':''}><span>${label('consent')}</span></label>`;
 if(step===5)content=`<dl class="summary-list">${[['type',data.project_type],['budget',data.budget],['deadline',data.deadline],['description',data.description],['name',data.name],['contactMethod',data.method],['contactValue',data.contact]].map(([k,v])=>`<dt>${label(k)}</dt><dd>${esc(t(v))}</dd>`).join('')}</dl><div id="turnstile" style="margin-top:20px"></div>`;
 host.innerHTML=`<form id="brief"><span class="mono">0${step+1} / 06</span><div class="form-progress">${keys.map((_,i)=>`<i class="${i<=step?'active':''}"></i>`).join('')}</div><h3 tabindex="-1">${label(keys[step])}</h3>${content}<label class="honey" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off" value="${esc(data.website)}"></label><div class="form-actions"><button type="button" id="form-back" class="text-btn" ${step===0?'hidden':''}>← ${label('back')}</button><button class="btn" type="submit" ${submitting?'disabled':''}>${label(submitting?'sending':step===5?'send':'next')} →</button></div><p class="form-error" id="form-error" role="alert"></p></form>`;
 const form=host.querySelector('form');form.addEventListener('input',()=>{read();if(!started){started=true;track('form_start')}});form.addEventListener('change',read);host.querySelector('#form-back').onclick=()=>{read();step--;renderForm();host.querySelector('h3').focus()};form.onsubmit=async e=>{e.preventDefault();read();if(step===4&&!validContact()){message('invalid');return}if(step<5){track('form_step_completed',{step:step+1});step++;renderForm();host.querySelector('h3').focus();return}await submit()};
 if(step===5&&configured()&&config.turnstileSiteKey)mountCaptcha();if(!configured())message('offline');
}
function validContact(){const v=data.contact.trim();return data.name.trim().length>=2&&(data.method==='email'?/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v):data.method==='Telegram'?/^@[a-zA-Z0-9_]{5,32}$/.test(v):/^\+?[\d\s()\-]{7,25}$/.test(v)&&v.replace(/\D/g,'').length>=7)}
async function mountCaptcha(){try{if(!window.turnstile){await new Promise((resolve,reject)=>{let script=document.querySelector('#captcha-script');if(script){script.addEventListener('load',resolve,{once:true});script.addEventListener('error',reject,{once:true});return}script=document.createElement('script');script.id='captcha-script';script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.onload=resolve;script.onerror=reject;document.head.append(script)})}if(step!==5||!document.querySelector('#turnstile'))return;widget=window.turnstile.render('#turnstile',{sitekey:config.turnstileSiteKey,language:language==='kz'?'auto':language,action:'lead',callback:v=>token=v,'expired-callback':()=>token='','error-callback':()=>{token='';message('captcha')}})}catch{message('captcha')}}
async function submit(){if(submitting)return;if(!configured()){message('offline');return}if(!token){message('captcha');return}submitting=true;const btn=document.querySelector('#brief button[type=submit]');btn.disabled=true;btn.textContent=t('sending');track('form_submit');try{success=await intake({kind:'lead',...data,...firstTouch,language,session_id:consent()==='yes'?getSession():null,captcha_token:token});if(!success?.lead_id)throw Error('error');track('lead_created');renderForm()}catch{message('error');token='';if(widget!==undefined)window.turnstile.reset(widget)}finally{submitting=false;if(btn?.isConnected){btn.disabled=false;btn.textContent=t('send')+' →'}}}
export function initForm(){renderForm();window.addEventListener('languagechange',()=>{read();renderForm()})}
